"""Independent checker (does not import wfm). usage: check.py litware|northwind <week> <outdir> [datafile]"""
import sys, math, json, csv
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from collections import defaultdict
import pandas as pd

client, week, outdir = sys.argv[1:4]
datafile = sys.argv[4] if len(sys.argv) > 4 else None
SPEC = {
 "litware": dict(tz="Europe/London", g=20, hours=(7,21), sla={"priority":(.9,30),"standard":(.8,30),"email":(.8,300)}, bound=1.45,
                 qhours={}, floor={"priority":(2,7,21)}, stamp="end", file="data/litware/export_%s.csv", agents="data/agents/litware.csv", noearly={"email":9}),
 "northwind": dict(tz="America/Chicago", g=30, hours=(6,24), sla={"priority":(.9,30),"standard":(.8,20),"vip":(.9,20)}, bound=1.57,
                 qhours={"vip":(8,20)}, floor={"vip":(1,6,24)}, stamp="start", file="data/northwind/export_%s.csv", agents="data/agents/northwind.csv", noearly={}),
}[client]
TZ=ZoneInfo(SPEC["tz"]); G=SPEC["g"]; step=timedelta(minutes=G)
def erlB(a,n):
    b=1.0
    for k in range(1,n+1): b=a*b/(k+a*b)
    return b
def slv(a,n,aht,t):
    if n<=a: return 0.0
    b=erlB(a,n); c=n*b/(n-a*(1-b)); return 1-c*math.exp(-(n-a)*t/aht)
def req(v,aht,q):
    a=v*aht/(G*60)
    if a<=0: return 0
    tg,t=SPEC["sla"][q]; n=max(1,math.floor(a)+1)
    while not(slv(a,n,aht,t)>=tg and a/n<=0.85+1e-12): n+=1
    return n
yr,wk=week.split("-W"); mon=date.fromisocalendar(int(yr),int(wk),1)
start=datetime(mon.year,mon.month,mon.day,tzinfo=TZ).astimezone(timezone.utc)
nxt=mon+timedelta(days=7); end=datetime(nxt.year,nxt.month,nxt.day,tzinfo=TZ).astimezone(timezone.utc)
grid=[]; t=start
while t<end: grid.append(t); t+=step
gi={t:i for i,t in enumerate(grid)}
d=pd.read_csv(datafile or ("/app/"+SPEC["file"]%week))
col="interval_end_local" if SPEC["stamp"]=="end" else "interval_start_local"
V=defaultdict(float); A={}
for r in d.itertuples(index=False):
    lab=datetime.strptime(getattr(r,col),"%Y-%m-%d %H:%M"); sign=1 if r.utc_offset[0]=="+" else -1
    off=timedelta(hours=int(r.utc_offset[1:3]),minutes=int(r.utc_offset[4:6]))*sign
    u=(lab-off).replace(tzinfo=timezone.utc)
    if SPEC["stamp"]=="end": u-=step
    u=datetime.fromtimestamp(u.timestamp()//(G*60)*(G*60),tz=timezone.utc)
    if u not in gi: print("row outside week",r); continue
    V[(r.queue,u)]+=r.volume; A[(r.queue,u)]=r.aht_sec if r.volume>0 or (r.queue,u) not in A else A[(r.queue,u)]
queues=list(SPEC["sla"])
def opq(q,t):
    l=t.astimezone(TZ); h=l.hour+l.minute/60; lo,hi=SPEC["qhours"].get(q,SPEC["hours"]); return lo<=h<hi
R={q:[req(V[(q,t)],A.get((q,t),300),q) if opq(q,t) else 0 for t in grid] for q in queues}
s=pd.read_csv(f"{outdir}/schedule.csv")
for c in ("segment_start_utc","segment_end_utc","break_start_utc"): s[c]=pd.to_datetime(s[c],utc=True)
ag=pd.read_csv("/app/"+SPEC["agents"]).set_index("agent_id")
viol=defaultdict(list)
gross={q:[0]*len(grid) for q in queues}; brk={q:[0]*len(grid) for q in queues}
for r in s.itertuples(index=False):
    ss,ee=r.segment_start_utc.to_pydatetime(),r.segment_end_utc.to_pydatetime()
    if r.queue not in str(ag.loc[r.agent_id,"skills"]).split(";"): viol["skill"].append(r.agent_id)
    for t in grid:
        if ss<=t<ee: gross[r.queue][gi[t]]+=1
    if r.break_minutes and r.break_minutes>0:
        bs=r.break_start_utc.to_pydatetime()
        for t in grid:
            if bs<t+step and t<bs+timedelta(minutes=int(r.break_minutes)): brk[r.queue][gi[t]]+=1
    lo=SPEC["noearly"].get(r.queue)
    if lo is not None:
        l=ss.astimezone(TZ)
        if l.hour+l.minute/60<lo: viol["email_start"].append((r.agent_id,str(ss)))
# per agent
byag=defaultdict(list)
for r in s.itertuples(index=False): byag[r.agent_id].append(r)
for a,rows in byag.items():
    rows.sort(key=lambda r:r.segment_start_utc)
    tot=sum((r.segment_end_utc-r.segment_start_utc).total_seconds() for r in rows)/3600
    cap=40 if ag.loc[a,"contract"]=="FT" else 24
    if tot>cap+1e-9: viol["hours"].append((a,tot))
    for x,y in zip(rows,rows[1:]):
        if y.segment_start_utc<x.segment_end_utc: viol["overlap"].append(a)
    days=defaultdict(list)
    for r in rows: days[r.segment_start_utc.astimezone(TZ).date()].append(r)
    ds=sorted(days); run=1
    for d1,d2 in zip(ds,ds[1:]):
        run=run+1 if (d2-d1).days==1 else 1
        if run>5: viol["consec"].append(a)
    for d1,d2 in zip(ds,ds[1:]):
        gap=days[d2][0].segment_start_utc-days[d1][-1].segment_end_utc
        if gap<timedelta(hours=11): viol["rest"].append((a,str(d1),gap))
    for dd,rs in days.items():
        if len(rs)>1 and ag.loc[a,"contract"]!="PT": viol["split"].append((a,str(dd)))
        # one queue per day
        if len({r.queue for r in rs})>1: viol["multi_queue_day"].append((a,str(dd)))
        h=sum((r.segment_end_utc-r.segment_start_utc).total_seconds() for r in rs)/3600
        b=[r for r in rs if r.break_minutes and r.break_minutes>0]
        if h>=6:
            if len(b)!=1 or b[0].break_minutes!=20: viol["break_count"].append((a,str(dd))); continue
            b=b[0]; sst=rs[0].segment_start_utc; off=(b.break_start_utc-sst).total_seconds()/3600
            if not(2-1e-9<=off<=5+1e-9) or b.break_start_utc+timedelta(minutes=20)>b.segment_end_utc: viol["break_window"].append((a,str(dd),off))
            q=b.queue
            cands=[t for t in grid if t>=sst+timedelta(hours=2)-timedelta(seconds=0) and t<=sst+timedelta(hours=5) and any(r.segment_start_utc<=t and t+timedelta(minutes=20)<=r.segment_end_utc for r in rs)]
            best=max(gross[q][gi[t]]-R[q][gi[t]] for t in cands)
            bt=b.break_start_utc.to_pydatetime()
            if gross[q][gi[bt]]-R[q][gi[bt]]!=best: viol["break_surplus"].append((a,str(dd),gross[q][gi[bt]]-R[q][gi[bt]],best))
        elif b: viol["break_short_shift"].append((a,str(dd)))
# floors
for q,(n,lo,hi) in SPEC["floor"].items():
    for i,t in enumerate(grid):
        l=t.astimezone(TZ); h=l.hour+l.minute/60
        if lo<=h<hi and gross[q][i]<n: viol["floor"].append((q,str(t)))
# attainment
exc=[]
sla={}
for q in queues:
    met=tot=0
    for i,t in enumerate(grid):
        l=t.astimezone(TZ); h=l.hour+l.minute/60
        if not(SPEC["hours"][0]<=h<SPEC["hours"][1]) and q not in SPEC["qhours"]: continue
        if not opq(q,t): continue
        lo=SPEC["noearly"].get(q)
        if lo is not None and R[q][i]>0 and h<lo: exc.append((q,t)); continue
        tot+=1; met+= (gross[q][i]-brk[q][i])>=R[q][i]
    sla[q]=met/tot
hrs=((s.segment_end_utc-s.segment_start_utc).dt.total_seconds()/3600).sum()
reqh=sum(sum(R[q]) for q in queues)*G/60
print("intervals",len(grid),"sla",{k:round(v,3) for k,v in sla.items()},"hours",round(hrs,1),"req",round(reqh,1),"ratio",round(hrs/reqh,3),"bound",SPEC["bound"])
print("exceptions",len(exc),"agents",s.agent_id.nunique())
print("VIOLATIONS",{k:len(v) for k,v in viol.items()} or "none")
for k,v in viol.items(): print(k,v[:3])
ev=json.load(open(f"{outdir}/eval.json"))
print("eval sla",ev["sla"],"diff",{q:round(abs(ev['sla'][q]-sla[q]),3) for q in queues})
print("OK" if not viol and hrs<=SPEC["bound"]*reqh and all(abs(ev['sla'][q]-sla[q])<=0.005 for q in queues) else "PROBLEM")
E
